(function () {
  var d = (dec && dec.data) ? dec.data : {};
  var acct = String(d.distributor_account_id || '');
  var row = (dists && dists[acct]) ? dists[acct] : null;
  // The projection carries the OUTCOME, never the answers: the distributor
  // already holds the answers (they are the broker's), and the ingress
  // allowlist is the control on what crosses the other way.
  var projection = {
    quote_id: String(d.quote_id || ''),
    submission_version: Number(d.submission_version || 0),
    quote_reference: String(d.quote_reference || ''),
    outcome: String(d.outcome || ''),
    outcome_status: String(d.decision_status === 'ISSUED' ? 'ISSUED'
                        : d.decision_status === 'DECLINED' ? 'DECLINED'
                        : d.outcome === 'DECLINE' ? 'DECLINED'
                        : d.outcome === 'BOUND' ? 'BOUND'
                        : d.outcome === 'SANCTION_REFERRAL' ? 'SANCTION_REFERRAL'
                        : 'REFERRED'),
    product_code: String(d.product_code || ''),
    product_version: String(d.product_version || ''),
    decision_seq: Number(d.decision_seq || 0),
    decided_at: String(d.decided_at || ''),
    total_payable: Number(d.total_payable || 0),
    premium_breakdown: {
      base_premium: Number(d.base_premium || 0),
      broker_commission: Number(d.broker_commission || 0),
      fsl_levy: Number(d.fsl_levy || 0),
      gst: Number(d.gst || 0),
      stamp_duty: Number(d.stamp_duty || 0),
      premium_basis: String(d.premium_basis || '')
    },
    reasons: Array.isArray(d.broker_reasons) ? d.broker_reasons : [],
    documents: Array.isArray(d.issued_document_refs) ? d.issued_document_refs : [],
    quote_validity_expiry: String(d.quote_validity_expiry || ''),
    policy_number: String(d.policy_number || ''),
    bound_at: String(d.bound_at || '')
  };
  return {
    deliverable: row !== null && projection.quote_id !== '' && projection.submission_version > 0,
    reason: row === null ? ('no distributor registered for account ' + acct)
          : (projection.quote_id === '' ? 'decision carries no quote_id'
          : (projection.submission_version > 0 ? '' : 'decision carries no submission_version')),
    distributor_account_id: acct,
    endpoint: row ? String(row.decision_url || '') : '',
    projection: projection
  };
})();
